'use strict';
var originalSellerCard=orderCard;
orderCard=function(o){let html=originalSellerCard(o);if(o.delivery){const c=state.couriers?.find(c=>c.id===o.delivery.courierId),position=geoFresh(c);html=html.replace('</article>',`<div class="handoff-summary"><strong>Kuryer: ${esc(c?.name||'—')}</strong><button class="btn small" type="button" data-action="seller-live" data-id="${esc(o.id)}">Kuryer xaritasi</button><p>${courierPhase(o)==='at_restaurant'?'Kuryer restoranda. Kodni tekshirib paketlarni topshiring.':o.delivery.status==='assigned'?'Kuryer restoranga kelmoqda.':o.delivery.status==='picked_up'?'Kuryer buyurtmani olib ketgan.':'Yetkazish holati yangilangan.'}</p>${o.delivery.handoffConfirmedAt&&o.delivery.status==='assigned'?'<span class="tag success">Sotuvchi tasdiqladi · kuryer qabul qilishi kutilmoqda</span>':''}${position?`<p>GPS: ${esc(geoLabel(position))} · aniqlik ±${Math.round(position.accuracy)} m</p>`:'<p>Jonli GPS ulashilmagan yoki nuqta eskirgan.</p>'}</div></article>`);}return html;};
function sellerHandoffModal(id){state=load();const o=state.orders.find(o=>o.id===id&&canBranch(state,o.branch));if(!o)return;if(!o.delivery){toast('Avval kuryer shu buyurtmani o‘z panelidan qabul qilsin.');return;}if(o.delivery.handoffConfirmedAt){openModal('Topshirish tasdiqlangan','<p>Kuryer o‘z panelida “Buyurtmani oldim” deb tasdiqlashi kutilmoqda.</p>');return;}if(courierPhase(o)!=='at_restaurant'){toast('Kuryer avval “Restorandaman” bosqichini belgilasin.');return;}const c=state.couriers?.find(c=>c.id===o.delivery.courierId);openModal('Kuryerga topshirish',`<p><strong>#${esc(o.id)}</strong> · ${esc(c?.name||'Kuryer')}</p><ul class="order-items">${o.items.map(i=>`<li>${i.qty} × ${esc(i.name)}</li>`).join('')}</ul><p>Paketlar: ${o.packageCount??'Kiritilmagan'}</p>${field('Kuryer ko‘rsatgan 6 xonali kod','handoffCode','','text','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="off"')}<label class="check"><input type="checkbox" name="packagesConfirmed" required>Taom va paketlarni tekshirdim, kuryerga topshiryapman</label><p class="subtitle">Kod kuryerning faol yetkazmasida ko‘rinadi. Tasdiqdan keyin kuryer “Buyurtmani oldim” tugmasini bosadi.</p>`,'seller-handoff-form',`data-id="${esc(id)}"`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="complete"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(!sellerActionAllowed(state,'complete',b.dataset.id))return;sellerHandoffModal(b.dataset.id);},true);
document.addEventListener('submit',e=>{const form=e.target;if(form.id!=='seller-handoff-form')return;e.preventDefault();e.stopImmediatePropagation();if(!form.reportValidity())return;const f=new FormData(form);try{if(!f.has('packagesConfirmed'))throw Error('Paketlar topshirilishini tasdiqlang.');if(update(s=>sellerApproveHandoff(s,form.dataset.id,String(f.get('handoffCode')||'')))){closeModal();render();toast('Topshirish tasdiqlandi. Kuryer buyurtmani qabul qilsin.');}}catch(error){$('#form-error').textContent=error.message;}},true);
var sellerBaseDeliveryModal=sellerDeliveryModal;
sellerDeliveryModal=function(id){sellerBaseDeliveryModal(id);const form=$('#delivery-info-form');if(!form)return;const o=state.orders.find(o=>o.id===id);form.insertAdjacentHTML('beforeend',`<div class="geo-editor"><h3>Xaritadagi nuqtalar</h3><p class="subtitle">Restoran yoki mijozni tanlang, so‘ng xaritada kerakli joyni bosing. Matnli manzilning o‘zi koordinataga avtomatik aylantirilmaydi.</p><div class="actions"><button type="button" class="btn" id="pick-restaurant">Restoran nuqtasi</button><button type="button" class="btn" id="pick-customer">Mijoz nuqtasi</button><button type="button" class="btn" id="seller-gps">Restoran uchun GPS nuqtam</button></div><p id="geo-edit-status" role="status">Tanlangan: restoran</p><div id="seller-map" class="live-map"></div><div class="form-row">${field('Restoran kengligi (lat)','pickupLat',o.pickupLocation?.lat??'','number','min="-90" max="90" step="any"')}${field('Restoran uzunligi (lng)','pickupLng',o.pickupLocation?.lng??'','number','min="-180" max="180" step="any"')}</div><div class="form-row">${field('Mijoz kengligi (lat)','dropoffLat',o.dropoffLocation?.lat??'','number','min="-90" max="90" step="any"')}${field('Mijoz uzunligi (lng)','dropoffLng',o.dropoffLocation?.lng??'','number','min="-180" max="180" step="any"')}</div><p class="subtitle">Xarita rasmlari uchun internet kerak. GPS faqat tugmani bosganingizda so‘raladi.</p></div>`);let target='pickup',map,markers={};const set=(type,p)=>{form.elements[type+'Lat'].value=p.lat.toFixed(6);form.elements[type+'Lng'].value=p.lng.toFixed(6);if(map){markers[type]?.remove();markers[type]=L.marker([p.lat,p.lng]).addTo(map).bindTooltip(type==='pickup'?'Restoran':'Mijoz');}$('#geo-edit-status').textContent=(type==='pickup'?'Restoran':'Mijoz')+': '+geoLabel(p);};if(globalThis.L){map=L.map('seller-map').setView([41.3111,69.2797],12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);map.on('click',e=>set(target,{lat:e.latlng.lat,lng:e.latlng.lng}));if(o.pickupLocation)set('pickup',o.pickupLocation);if(o.dropoffLocation)set('dropoff',o.dropoffLocation);}else $('#seller-map').textContent='Xarita kutubxonasi yuklanmadi. Internetni tekshiring yoki koordinatalarni qo‘lda kiriting.';$('#pick-restaurant').onclick=()=>{target='pickup';$('#geo-edit-status').textContent='Restoran nuqtasini xaritada bosing.';};$('#pick-customer').onclick=()=>{target='dropoff';$('#geo-edit-status').textContent='Mijoz nuqtasini xaritada bosing.';};$('#seller-gps').onclick=()=>{if(!navigator.geolocation){$('#geo-edit-status').textContent='Brauzer GPSni qo‘llamaydi.';return;}navigator.geolocation.getCurrentPosition(p=>{const point=geoPoint(p.coords.latitude,p.coords.longitude);if(point&&document.contains(form)){set('pickup',point);map?.setView([point.lat,point.lng],16);}},()=>{if(document.contains(form))$('#geo-edit-status').textContent='GPS olinmadi. Ruxsat va HTTPS/localhost manzilini tekshiring.';},{enableHighAccuracy:true,timeout:15000,maximumAge:0});};};
var originalHistoryWithGps=historyTable;
historyTable=function(list){return originalHistoryWithGps(list)+list.filter(o=>o.delivery?.status==='picked_up').map(o=>`<div class="handoff-summary"><strong>#${esc(o.id)} · Yetkazilmoqda</strong><button class="btn small" type="button" data-action="seller-live" data-id="${esc(o.id)}">Kuryerni xaritada ko‘rish</button></div>`).join('');};
let sellerLiveOrder='',sellerLiveMap=null,sellerLiveLayer=null;
function updateSellerLive(){const el=$('#seller-live-map');if(!el||!el.isConnected)return;const fresh=load(),o=fresh.orders.find(o=>o.id===sellerLiveOrder&&canBranch(fresh,o.branch));if(!o)return;const c=fresh.couriers?.find(c=>c.id===o.delivery?.courierId),point=geoFresh(c);$('#seller-live-status').textContent=point?`${c.name} · aniqlik ±${Math.round(point.accuracy)} m · ${new Date(point.at).toLocaleTimeString('uz-UZ')}`:'Kuryer GPSni ulashmayapti yoki oxirgi nuqta 1 daqiqadan eski.';if(!globalThis.L)return;if(!sellerLiveMap){sellerLiveMap=L.map(el).setView([41.3111,69.2797],12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(sellerLiveMap);sellerLiveLayer=L.layerGroup().addTo(sellerLiveMap);}sellerLiveLayer.clearLayers();const points=[];for(const [p,label] of [[o.pickupLocation,'Restoran'],[o.dropoffLocation,'Mijoz'],[point,'Kuryer GPS']]){if(!p)continue;points.push([p.lat,p.lng]);L.marker([p.lat,p.lng]).addTo(sellerLiveLayer).bindTooltip(label);}if(points.length)sellerLiveMap.fitBounds(points,{padding:[25,25],maxZoom:16});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="seller-live"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const o=state.orders.find(o=>o.id===b.dataset.id&&canBranch(state,o.branch));if(!o)return;sellerLiveMap?.remove();sellerLiveMap=null;sellerLiveLayer=null;sellerLiveOrder=o.id;openModal('Kuryer GPS joylashuvi','<p id="seller-live-status" role="status"></p><div id="seller-live-map" class="live-map"></div><p class="subtitle">Faqat kuryer ulashgan yangi nuqta ko‘rsatiladi. Boshqa telefon bilan ulanish uchun server kerak.</p>');updateSellerLive();},true);
window.addEventListener('storage',e=>{if(e.key===COURIER_STORE)updateSellerLive();});
setInterval(updateSellerLive,15000);
render();
